  $('#svcSearch').on('input',function(){table.search(this.value).draw()});
  function criticality(){var max=0;$('.svc-score-select').each(function(){max=Math.max(max,parseInt(this.value,10)||0)});$('#svcCriticality').text(({1:'BAJO',2:'MEDIO',3:'ALTO',4:'MUY ALTO'})[max]||'SIN EVALUAR')}
  $('.svc-score-select').on('change',criticality);
