  $('.btn-edit-service').on('click',function(){var data=$(this).data('record'),form=$('#formServicioTI')[0];if(typeof data==='string')data=JSON.parse(data);form.reset();syncServiceCsrf();Object.keys(data).forEach(function(key){if(!/^\d+$/.test(key)&&['_csrf','action','csrf_token'].indexOf(key)<0&&form.elements.namedItem(key)&&data[key]!==null)$(form.elements.namedItem(key)).val(data[key])});syncServiceCsrf();form.elements.IdServicio.value=data.IdServicio;form.elements.FechaInicio.readOnly=!!data.IdPeriodoVigente;form.elements.FechaFin.readOnly=!!data.IdPeriodoVigente;criticality();$('#modalServicioTI .modal-title').html('<i class="fas fa-edit mr-2"></i>Editar servicio TI');$('#modalServicioTI').modal('show')});
    var contractTable=$('#tblServiciosContratos').DataTable({language:DATATABLES_SPANISH,pageLength:10,lengthMenu:[10,20,30,50],order:[[0,'asc']],autoWidth:false,dom:'rt<"d-flex justify-content-between align-items-center flex-wrap p-3"lip>'});
    var hash=location.hash;if(hash&&$(hash).hasClass('tab-pane'))$('.svc-tabs a[href="'+hash+'"]').tab('show');
    $('.svc-tabs a').on('shown.bs.tab',function(e){history.replaceState(null,'',e.target.hash);table.columns.adjust();contractTable.columns.adjust()});
